INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ACE','Pokémon Ace');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ACE_HELP','Great General replacement with 3 Movement. Retains the normal aura and Citadel actions while detached. Attach to an adjacent military unit for +15% Combat Strength, +50% combat Training, 5 HP each turn and Battle Item. A bonded team member uses 90% Training thresholds and gains +1 Sight at Legendary. Detach in friendly territory.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ACE_PEDIA','Some trainers follow Red for the trophies he earned. The finest follow him for the care he gives his partners. A Pokémon Ace offers patient instruction and a steady hand when a veteran faces its hardest battle. Attachment withdraws the trainer from the map until the bond is ended.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ADJECTIVE','Indigo');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_AIRLIFT','Airlift selected unit');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ASSIGN','Assign selected candidate');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ATTACH','Attach Ace');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_BLASTOISE','Blastoise — Unbreakable Torrent');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_BLASTOISE_HELP','+25% Defence, 25% less incoming ranged damage. If alive after melee defence, retaliate for 10 damage. Can fortify immediately after attacking where supported.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_BLOOM_STATUS','Ancient Bloom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_BLOOM_STATUS_HELP','-15% Combat Strength and -1 Movement this turn. Applied once when starting next to enemy Venusaur; removable by Battle Item.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_BOND','Trainer Bond');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_BOND_HELP','+15% Combat Strength, +50% combat Training, 5 HP each turn, Battle Item. Team rank thresholds reduced by 10%.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CANDIDATE','Next eligible unit');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CAUGHT','Caught');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CAUGHT_HELP','0 Training. No combat bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CENTER','Pokémon Center');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CENTER_HELP','Hospital replacement at Biology. Same Production cost; 4 Gold maintenance. +5 Food, 25% Food retained, +5 city healing. Healing military units in its owned three-tile territory recover 15 extra HP. Team members stationed here gain 3 Training per Standard-speed turn, capped at 65. Newly trained military units start with 15 Training. Upgrading here refunds 25% of the paid upgrade price. One explicit airlift departure per city per turn between legal airlift cities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CENTER_PEDIA','A journey continues because someone opens the door when its travellers are tired. The Pokémon Center gives Red''s partners a place to recover, and young trainers a place to learn that strength begins with care.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CHAMPION','Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CHAMPION_HELP','65 Training. +15% Combat Strength; +1 Movement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CHARIZARD','Charizard — Blazing Ace');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CHARIZARD_HELP','+1 Range for ranged units without another range bonus, +25% attack against cities and fortified units, ignore terrain movement costs. Attacks splash 5 damage onto enemies adjacent to the target. A melee partner retains melee attacks.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_1','Pallet Town');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_10','Cinnabar Island');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_11','Indigo Plateau');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_12','Mt. Moon');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_13','Rock Tunnel');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_14','Safari Zone');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_15','Seafoam Islands');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_16','Power Plant');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_17','Victory Road');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_18','Route 22');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_19','Pokémon Tower');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_2','Viridian City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_20','Mt. Silver');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_3','Pewter City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_4','Cerulean City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_5','Vermilion City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_6','Lavender Town');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_7','Celadon City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_8','Fuchsia City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CITY_9','Saffron City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CIV','The Indigo Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CIV5','The Indigo Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CIV5_HEADING_1','From Pallet Town to the Summit');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CIV5_TEXT_1','Pallet Town is a quiet beginning for an extraordinary journey. Across Kanto, Red challenged Gym Leaders, overcame his rival and earned the title of Champion. The Indigo Champion represents the discipline that outlasted those victories: a small team raised with patience, loyalty and trust.[NEWLINE][NEWLINE]After conquering the League, Red left public life for Mt. Silver. Far above the roads that had carried him to fame, the Champion became the silent measure against which every challenger would be tested.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CIV_PEDIA','Pallet Town is a quiet beginning for an extraordinary journey. Across Kanto, Red challenged Gym Leaders, overcame his rival and earned the title of Champion. The Indigo Champion represents the discipline that outlasted those victories: a small team raised with patience, loyalty and trust.[NEWLINE][NEWLINE]After conquering the League, Red left public life for Mt. Silver. Far above the roads that had carried him to fame, the Champion became the silent measure against which every challenger would be tested.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_DAWN','From the quiet paths of Pallet Town, a young trainer set forth with a dream and a faithful companion. Across Kanto he travelled, challenging leaders, defeating rivals and overcoming the greatest trainers of his generation.[NEWLINE][NEWLINE]He became Champion, yet a title could not define him. Leaving fame behind, he ascended the frozen heights of Mt. Silver. There he trained in silence, until the boy from Pallet Town had become a legend.[NEWLINE][NEWLINE]And now, Red, the world awaits your return. Will you once more become the very best?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_DESTINATION','Destination');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_DETACH','Detach Ace');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_DETAILS','Inspect');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_GREETING_1','... [Red silently adjusts his cap.]');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_HORIZON','Across Every Horizon');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_HORIZON_HELP','Embarked near friendly Lapras: +1 Movement and +15% Defence.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_INTERNAL','The Living Legend');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_INTERNAL_HELP','Automatically maintained civilization effect.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_ITEM','Battle Item');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_JOURNEY','Journey to Mt. Silver');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_JOURNEY_HELP','One-time project: Modern Era, four living team members and one Legendary partner. Cost is 65% of the active Statue of Liberty baseline, scaled by native project speed. Withdraws the current team for eight Standard-speed turns; all cities suffer -10% Gold and Production. Returning veterans upgrade freely along available legal lines, become Legendary and Summit-Trained, and receive distinct Pokémon identities. Never creates replacement partners.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_JOURNEY_PEDIA','The Champion leaves the applause behind. Snow erases the path to Mt. Silver, and the world wonders whether Red will ever return. His companions know: the journey was never finished.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_LAPRAS','Lapras — Across Every Horizon');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_LAPRAS_HELP','Ocean access for naval partners; amphibious and safe embarkation for land partners. +1 Range without another range bonus. Friends embarked within two tiles gain +1 Movement and +15% Defence. +25% damage against naval or embarked targets.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_LEADER','Trainer Red');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_LEADER_PEDIA','Red rarely needs words. From his first steps beyond Pallet Town to his final vigil on Mt. Silver, his answer to uncertainty has been practice. His companions are partners, never disposable soldiers. In Gold, Silver, Crystal, HeartGold and SoulSilver, the summit encounter reveals what that persistence has made of the young trainer: the final challenge awaiting those who thought their journey complete.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_LEGENDARY','Legendary');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_LEGENDARY_HELP','100 Training. +20% Combat Strength; heal 10 after attacking and defeating a unit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PANEL_HELP','Select a partner or candidate, then use explicit actions. Attach requires a nearby Ace; detach requires friendly territory. Battle Item cannot follow an attack. Airlift cycles legal destinations with the destination button. Rendering this panel never changes gameplay.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PIKACHU','Pikachu — Partner Above All');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PIKACHU_HELP','+2 Movement; +25% strength against stronger base opponents. Attacks against full-health units deal 10 extra damage. A lethal melee attack can be evaded to a legal nearby tile once per five Standard-speed turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PLATEAU','Indigo Plateau');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PLATEAU_HELP','Heroic Epic replacement; inherits Barracks and national-wonder requirements. +15% military Production and Morale for trained units. Unlocks six team slots. Team members beginning turns in the capital gain 2 Training. The capital gains 1 Culture and Science per team rank (0–4). Each first rival original capital adds 2 Culture, 2 Science and 1 Happiness here, to five captures.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PLATEAU_PEDIA','Beyond Victory Road stands a place where preparation is tested and a trainer''s companions become a team. Indigo Plateau remembers every hard-earned victory. Its Hall of Fame honours the partners who were there, rather than those who joined afterwards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PROVEN','Proven');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_PROVEN_HELP','35 Training. +10% Combat Strength; +5 HP whenever healed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_RETURN','Red has returned from the summit.[NEWLINE][NEWLINE]No proclamation announces his arrival. No great army marches beneath his banner. Only six companions stand at his side.[NEWLINE][NEWLINE]Those who would claim the title of greatest must now challenge the legend himself.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_RETURN_TITLE','The Legend Has Returned');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_RIBBON','Champion Ribbon');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_RIBBON_HELP','+3% Combat Strength per Ribbon, at most five. Earned by current team members on each first rival original-capital capture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SELECT','Select');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SHORT','Indigo Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SILENT_1','...');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SNORLAX','Snorlax — The Sleeping Mountain');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SNORLAX_HELP','+40% Defence while fortified, 15 HP healing per fortified turn, maximum 1 Movement. Resists displacement and stops land movement between adjacent tiles even through normal Zone of Control immunity. See engine limits for third-party forced movement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_1','Blue');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_10','Lucas');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_2','Leaf');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_3','Chase');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_4','Elaine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_5','Ethan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_6','Lyra');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_7','Kris');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_8','Brendan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SPY_9','May');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_STRATEGY','Protect your veterans. Fight worthy opponents, heal in Pallet Town and build Indigo Plateau to assemble a six-member team. Pokémon Centers sustain the army; Pokémon Aces strengthen individual partners. Keep your empire safe during the Journey to Mt. Silver. On their return, use each identity to support the others. Domination is preferred, with Science as a strong alternative.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SUMMIT','Summit-Trained');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_SUMMIT_HELP','+15% Combat Strength, +10 maximum HP, ignore enemy Zone of Control, heal 10 after a kill, generate no additional combat War Weariness, and move after attacking with movement remaining.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TEAM','Champion Team');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TEAM_HELP','Up to six Champion-rank non-air partners. +25% combat experience, cannot be captured, and heal 5 when another partner wins within three tiles. Initial capacity 2; Classical 3; Medieval 4; first national wonder 6. Dead partners are never restored.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TITLE','The Silent Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINED','Trained');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINED_HELP','15 Training. +5% Combat Strength.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER','Trainer Red');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER_HEADING_1','A Legend in Silence');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER_LIVED','The Age of the Indigo League');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER_NAME','Trainer Red');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER_SUBTITLE','The Silent Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER_TEXT_1','Red rarely needs words. From his first steps beyond Pallet Town to his final vigil on Mt. Silver, his answer to uncertainty has been practice. His companions are partners, never disposable soldiers. In Gold, Silver, Crystal, HeartGold and SoulSilver, the summit encounter reveals what that persistence has made of the young trainer: the final challenge awaiting those who thought their journey complete.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINER_TITLES_1','Champion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINING','Pokémon Training');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAINING_HELP','Kills +10; surviving an opponent with at least 15% greater base strength +5; city captures +15; camps +8; ending damaged in the capital +2. Ranks replace one another at 0/15/35/65/100. Only Proven has +5 whenever healed; only Champion has +1 Movement. Legendary heals 10 after an attacking kill.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAIT','The Living Legend');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_TRAIT_HELP','Train irreplaceable military partners through battle. Champion Team capacity grows from 2 to 6. Defeat the strongest fielded unit types for Culture and Science; capture original capitals for Ribbons. In the Modern Era, send four or more Champions, including a Legendary unit, to Mt. Silver. They return as Summit-Trained legends after eight Standard-speed turns. Open Champion Team for Training, Ace bonds and explicit actions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_VANISHED','Red has vanished from public life. Rumours place the former Champion atop Mt. Silver.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_VENUSAUR','Venusaur — Ancient Bloom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RED_VENUSAUR_HELP','At your turn start, adjacent friends heal 10 HP. Enemies starting adjacent suffer -15% Combat Strength and -1 Movement for that turn. +25% strength in Forest and Jungle. Effects do not stack.');
